import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useTheme } from '../context/ThemeContext';
import { searchProducts, adminLogout } from '../services/api';
import { isAdmin, getAdminUser, clearAuthData } from '../util/auth';
import AdminNotifications from './AdminNotifications';

// Direct function definition to avoid import issues
const isAdminAuthenticated = () => {
  const adminToken = localStorage.getItem('adminToken');
  return !!adminToken;
};

const ModernNavbar = ({ cartCount, user, onLogout }) => {
  const navigate = useNavigate();
  const { isDarkMode, toggleTheme } = useTheme();

  // Debug logging
  console.log('ModernNavbar - User state:', user);
  console.log('ModernNavbar - User exists:', !!user);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [showSearch, setShowSearch] = useState(false);
  const [adminAuthState, setAdminAuthState] = useState(isAdminAuthenticated());
  const [isScrolled, setIsScrolled] = useState(false);
  const [placeholderIndex, setPlaceholderIndex] = useState(0);

  // Get gradient colors for fallback background
  const getCategoryGradient = (category) => {
    const gradients = {
      milk: 'from-blue-200 to-blue-400 dark:from-blue-800 dark:to-blue-600',
      ghee: 'from-amber-200 to-amber-400 dark:from-amber-800 dark:to-amber-600',
      cheese: 'from-yellow-200 to-yellow-400 dark:from-yellow-800 dark:to-yellow-600',
      butter: 'from-orange-200 to-orange-400 dark:from-orange-800 dark:to-orange-600',
      curd: 'from-green-200 to-green-400 dark:from-green-800 dark:to-green-600',
      paneer: 'from-purple-200 to-purple-400 dark:from-purple-800 dark:to-purple-600',
      cream: 'from-pink-200 to-pink-400 dark:from-pink-800 dark:to-pink-600',
      yogurt: 'from-teal-200 to-teal-400 dark:from-teal-800 dark:to-teal-600',
      lassi: 'from-cyan-200 to-cyan-400 dark:from-cyan-800 dark:to-cyan-600',
      buttermilk: 'from-lime-200 to-lime-400 dark:from-lime-800 dark:to-lime-600'
    };
    return gradients[category] || 'from-gray-200 to-gray-400 dark:from-gray-700 dark:to-gray-500';
  };

  // Get emoji for each category
  const getCategoryEmoji = (category) => {
    const emojis = {
      milk: '🥛',
      ghee: '🍯',
      cheese: '🧀',
      butter: '🧈',
      curd: '🥣',
      paneer: '🧊',
      cream: '🍦',
      yogurt: '🍶',
      lassi: '🥤',
      buttermilk: '🫙'
    };
    return emojis[category] || '🥛';
  };

  // Derive category from product name if not available
  const deriveCategoryFromName = (name) => {
    const lowerName = name?.toLowerCase() || '';
    if (lowerName.includes('milk')) return 'milk';
    if (lowerName.includes('ghee')) return 'ghee';
    if (lowerName.includes('cheese')) return 'cheese';
    if (lowerName.includes('butter')) return 'butter';
    if (lowerName.includes('curd')) return 'curd';
    if (lowerName.includes('paneer')) return 'paneer';
    if (lowerName.includes('cream')) return 'cream';
    if (lowerName.includes('yogurt')) return 'yogurt';
    if (lowerName.includes('lassi')) return 'lassi';
    if (lowerName.includes('buttermilk')) return 'buttermilk';
    return 'milk';
  };

  // Animated placeholder texts
  const placeholderTexts = [
    "",
    "🥛 ",
    "🍯🥛 ",
    "🍦🍯🥛 ",
    "🥤🍦🍯🥛 ",
    "🥣🥤🍦🍯🥛 ",
    "🧀🥤🍦🍯🧊🥛",
    "🧀🥤🍦🍯🧊🥛🧈",
    "🧀🥤🍦🍯🧊🥛🧈🫙",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊",
